nextflow_process {

    name "Test Process RMARKDOWNNOTEBOOK"
    script "../main.nf"
    process "RMARKDOWNNOTEBOOK"
    config "./nextflow.config"
    tag "modules"
    tag "modules_nfcore"
    tag "rmarkdownnotebook"

    test("test_rmarkdownnotebook") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test_rmd' ],
                    file(params.modules_testdata_base_path + 'generic/notebooks/rmarkdown/rmarkdown_notebook.Rmd', checkIfExists: true)
                ]
                input[1] = [:]
                input[2] = []
                """
            }
        }

        then {
            assertAll (
                { assert process.success },
                { assert snapshot(
                    file(process.out.report[0][1]).name,
                    process.out.parameterised_notebook,
                    process.out.artifacts,
                    file(process.out.session_info[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith("versions")}
                ).match() }
            )
        }
    }

    test("test_rmarkdownnotebook_parametrize") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test_rmd' ],
                    file(params.modules_testdata_base_path + 'generic/notebooks/rmarkdown/rmarkdown_notebook.Rmd', checkIfExists: true)
                ]
                input[1] = [input_filename: "hello.txt", n_iter: 12, input_dir: "./"]
                input[2] = file(params.modules_testdata_base_path + 'generic/txt/hello.txt', checkIfExists: true)
                """
            }
        }

        then {
            assertAll (
                { assert process.success },
                { assert snapshot(
                    file(process.out.report[0][1]).name,
                    process.out.parameterised_notebook,
                    process.out.artifacts,
                    file(process.out.session_info[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith("versions")}
                ).match() }
            )
        }
    }

    test("test_rmarkdownnotebook - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test_rmd' ],
                    file(params.modules_testdata_base_path + 'generic/notebooks/rmarkdown/rmarkdown_notebook.Rmd', checkIfExists: true)
                ]
                input[1] = [:]
                input[2] = []
                """
            }
        }

        then {
            assertAll (
                { assert process.success },
                { assert snapshot(
                    file(process.out.report[0][1]).name,
                    process.out.parameterised_notebook,
                    process.out.artifacts,
                    file(process.out.session_info[0][1]).name,
                    process.out.findAll { key, val -> key.startsWith("versions")}
                ).match() }
            )
        }
    }

}
